<?php
/**
 * EN / AR language switcher and RTL support.
 *
 * Client ask (2026-09-04): "Please add an EN/AR language switcher accessible
 * from the header on all pages, including product pages, cart, checkout and
 * footer/legal pages. Arabic should have proper RTL formatting."
 *
 * Translation engine: TranslatePress (free, wordpress.org). It translates the
 * rendered page in place — no duplicate pages or products, which matters on a
 * site whose layouts are regenerated by Niswah Starter — and sets
 * <html dir="rtl" lang="ar"> for Arabic on its own. RTL layout rules live in
 * style.css §17.
 *
 * The switcher is the theme's own [nb_lang] shortcode rather than
 * TranslatePress's dropdown: it renders "EN | AR" as two plain links built from
 * trp_custom_language_switcher(), which is easier to place in the 40px ticker
 * and to style. It sits in the ticker (generated header), so it is on every
 * page, every device. If TranslatePress is inactive the shortcode outputs
 * nothing and the ticker is unchanged.
 *
 * @package Niswah_Boutique
 */

if ( ! defined( 'ABSPATH' ) ) {
	exit;
}

class NB_Language {

	public static function init() {
		add_shortcode( 'nb_lang', array( __CLASS__, 'shortcode' ) );
		add_filter( 'body_class', array( __CLASS__, 'body_class' ) );
	}

	/**
	 * Languages from TranslatePress, or an empty array when it is not active.
	 *
	 * Each entry: code (e.g. en_US), language_name, current_page_url, plus a
	 * short label we add ("EN", "AR").
	 *
	 * @return array
	 */
	public static function languages() {
		if ( ! function_exists( 'trp_custom_language_switcher' ) ) {
			return array();
		}
		$langs = trp_custom_language_switcher();
		if ( ! is_array( $langs ) ) {
			return array();
		}
		$out = array();
		foreach ( $langs as $code => $lang ) {
			$short = strtoupper( substr( str_replace( '-', '_', $code ), 0, 2 ) );
			$out[ $code ] = array(
				'code'  => $code,
				'label' => $short,
				'name'  => isset( $lang['language_name'] ) ? $lang['language_name'] : $short,
				'url'   => isset( $lang['current_page_url'] ) ? $lang['current_page_url'] : home_url( '/' ),
			);
		}
		return $out;
	}

	/** Current TranslatePress language code, or '' when inactive. */
	public static function current() {
		global $TRP_LANGUAGE;
		return is_string( $TRP_LANGUAGE ) ? $TRP_LANGUAGE : '';
	}

	public static function shortcode() {
		$langs = self::languages();
		if ( count( $langs ) < 2 ) {
			return '';
		}
		$current = self::current();
		$parts   = array();
		foreach ( $langs as $code => $lang ) {
			$is_current = ( $code === $current );
			$parts[]    = sprintf(
				'<a class="nb-lang__item%s" href="%s" hreflang="%s" lang="%s"%s>%s</a>',
				$is_current ? ' is-current' : '',
				esc_url( $lang['url'] ),
				esc_attr( substr( $code, 0, 2 ) ),
				esc_attr( substr( $code, 0, 2 ) ),
				$is_current ? ' aria-current="true"' : '',
				esc_html( $lang['label'] )
			);
		}
		return '<span class="nb-lang" role="navigation" aria-label="' . esc_attr__( 'Language', 'niswah-boutique' ) . '">' . implode( '<span class="nb-lang__sep">|</span>', $parts ) . '</span>';
	}

	/** nb-lang-ar / nb-lang-en on <body>, handy for language-specific CSS. */
	public static function body_class( $classes ) {
		$current = self::current();
		if ( $current ) {
			$classes[] = 'nb-lang-' . sanitize_html_class( strtolower( substr( $current, 0, 2 ) ) );
		}
		return $classes;
	}
}

NB_Language::init();
